import FloatButton from "./FloatButton.js";
import BackTopWithInstall from "./BackTop.js";
import FloatButtonGroup from "./FloatButtonGroup.js";
import PurePanel from "./PurePanel.js";
//#region src/float-button/index.tsx
FloatButton.BackTop = BackTopWithInstall;
FloatButton.Group = FloatButtonGroup;
FloatButton._InternalPanelDoNotUseOrYouWillBeFired = PurePanel;
FloatButton.install = (app) => {
	app.component(FloatButton.name, FloatButton);
	app.component(FloatButtonGroup.name, FloatButtonGroup);
	app.component(BackTopWithInstall.name, BackTopWithInstall);
};
var float_button_default = FloatButton;
//#endregion
export { BackTopWithInstall as BackTop, FloatButtonGroup, float_button_default as default };
