import InternalUpload, { LIST_IGNORE } from "./Upload.js";
import Dragger from "./Dragger.js";
//#region src/upload/index.tsx
const Upload = InternalUpload;
Upload.Dragger = Dragger;
Upload.LIST_IGNORE = LIST_IGNORE;
Upload.install = (app) => {
	app.component(InternalUpload.name, Upload);
	app.component(Dragger.name, Dragger);
	return app;
};
const UploadDragger = Dragger;
//#endregion
export { UploadDragger, Upload as default };
