import { toTaggedKey } from "../util.js";
//#region src/VirtualList/useFlattenRows.ts
function useFlattenRows(data, groupData, getItemKey, group) {
	const flatRows = [];
	const groupKeys = [];
	const groupKeyToItems = /* @__PURE__ */ new Map();
	const itemRow = (item, index) => ({
		type: "item",
		item,
		index,
		taggedKey: toTaggedKey(getItemKey(item), "item")
	});
	if (!group) {
		data.forEach((item, index) => {
			flatRows.push(itemRow(item, index));
		});
		return {
			rows: flatRows,
			groupKeys,
			groupKeyToItems
		};
	}
	groupData.forEach((groupItems, groupKey) => {
		groupKeyToItems.set(groupKey, groupItems.map(({ item }) => item));
		groupKeys.push(groupKey);
		flatRows.push({
			type: "group",
			groupKey,
			taggedKey: toTaggedKey(groupKey, "group")
		});
		groupItems.forEach(({ item, index }) => {
			flatRows.push(itemRow(item, index));
		});
	});
	return {
		rows: flatRows,
		groupKeys,
		groupKeyToItems
	};
}
//#endregion
export { useFlattenRows as default };
