import { useForm, useFormInstance } from "./hooks/useForm.js";
import InternalForm from "./Form.js";
import InternalFormItem from "./FormItem/index.js";
//#region src/form/index.tsx
InternalForm.install = (app) => {
	app.component(InternalForm.name, InternalForm);
	app.component(InternalFormItem.name, InternalFormItem);
};
InternalForm.useForm = useForm;
InternalForm.useFormInstance = useFormInstance;
var form_default = InternalForm;
//#endregion
export { InternalFormItem as FormItem, form_default as default, useForm, useFormInstance };
