import Actions from "./Actions.js";
import Search from "./search.js";
import TransferSection from "./Section.js";
import Transfer from "./Transfer.js";
//#region src/transfer/index.tsx
const InternalTransfer = Transfer;
InternalTransfer.List = TransferSection;
InternalTransfer.Search = Search;
InternalTransfer.Operation = Actions;
InternalTransfer.install = (app) => {
	app.component(Transfer.name, Transfer);
	app.component(TransferSection.name, TransferSection);
	app.component(Search.name, Search);
	app.component(Actions.name, Actions);
	return app;
};
//#endregion
export { InternalTransfer as default };
