import { computed, shallowRef } from "vue";
//#region src/PickerInput/hooks/useFocusEvents.ts
/** Check whether the target belongs to any container. / 判断目标是否属于任意一个容器。 */
function isTargetInContainers(target, containers) {
	return containers.some((container) => !!container && (container === target || container.contains(target)));
}
/**
* Handle field focus and blur events.
* 处理 field 的聚焦与失焦事件。
*
* Always forward the actual element focus events. Only the internal Picker
* blur is skipped when `relatedTarget` still belongs to the Picker.
* 始终转发元素实际发生的焦点事件。仅当 `relatedTarget` 仍属于 Picker 时，
* 跳过 Picker 内部的整体失焦逻辑。
*/
function useFocusEvents(isInternalElement, onFocus, onBlur, onConfirmedBlur) {
	const focusedIndex = shallowRef(null);
	const onFieldFocus = (index, _source, event) => {
		focusedIndex.value = index;
		onFocus?.(index, event);
	};
	const onFieldBlur = (index, _source, event) => {
		if (!isInternalElement(event.relatedTarget)) {
			focusedIndex.value = null;
			onConfirmedBlur?.(index, event);
		}
		onBlur?.(index, event);
	};
	return [
		computed(() => focusedIndex.value !== null),
		onFieldFocus,
		onFieldBlur
	];
}
//#endregion
export { useFocusEvents as default, isTargetInContainers };
