import generateCalendar from "./generateCalendar.js";
import dayjsGenerateConfig from "@v-c/picker/generate/dayjs";
//#region src/calendar/index.tsx
const Calendar = generateCalendar(dayjsGenerateConfig);
Calendar.generateCalendar = generateCalendar;
Calendar.install = (app) => {
	app.component(Calendar.name, Calendar);
};
//#endregion
export { Calendar as default };
