import { isTargetInContainers } from "./useFocusEvents.js";
import { onUpdated, watch } from "vue";
//#region src/PickerInput/hooks/useFocusLock.ts
/**
* Keep focus on the specified input field while focus moves inside the Picker.
* 当焦点在 Picker 内移动时，将其锁定在指定的输入框上。
*/
function useFocusLock(index, forceFocus, selectorRef, popupRef, triggerOpen) {
	watch([index, forceFocus], () => {
		if (index.value !== null && forceFocus.value) {
			triggerOpen(true);
			selectorRef.value?.focus({ index: index.value });
		}
	}, { flush: "post" });
	const lockFocus = () => {
		if (index.value === null) return;
		const inputFields = [selectorRef.value?.startInput, selectorRef.value?.endInput];
		const activeElement = (inputFields[index.value]?.getRootNode())?.activeElement ?? document.activeElement;
		if (isTargetInContainers(activeElement, [popupRef.value])) return;
		if (inputFields.some((field, fieldIndex) => fieldIndex !== index.value && isTargetInContainers(activeElement, [field]))) inputFields[index.value]?.focus();
	};
	onUpdated(lockFocus);
}
//#endregion
export { useFocusLock as default };
