import getScroll, { isDocument, isWindow } from "./getScroll.js";
import { easeInOutCubic } from "./easings.js";
import raf from "@v-c/util/dist/raf";
//#region src/_util/scrollTo.ts
function scrollTo(y, options = {}) {
	const { getContainer = () => window, callback, duration = 450 } = options;
	const container = getContainer();
	const scrollTop = getScroll(container);
	const scroll = (top) => {
		if (isWindow(container)) container.scrollTo(window.pageXOffset, top);
		else if (isDocument(container)) container.documentElement.scrollTop = top;
		else container.scrollTop = top;
	};
	if (duration <= 0) {
		scroll(y);
		if (typeof callback === "function") callback();
		return () => {};
	}
	const startTime = Date.now();
	let rafId;
	const frameFunc = () => {
		const time = Date.now() - startTime;
		const nextScrollTop = easeInOutCubic(time > duration ? duration : time, scrollTop, y, duration);
		scroll(nextScrollTop);
		if (time < duration) rafId = raf(frameFunc);
		else if (typeof callback === "function") callback();
	};
	rafId = raf(frameFunc);
	return () => {
		raf.cancel(rafId);
	};
}
//#endregion
export { scrollTo as default };
