import KeyCode from "@v-c/util/dist/KeyCode";
//#region src/utils/keyUtil.ts
/** keyCode Judgment function */
function isValidateOpenKey(currentKeyCode) {
	return !!currentKeyCode && ![
		KeyCode.ESC,
		KeyCode.SHIFT,
		KeyCode.BACKSPACE,
		KeyCode.TAB,
		KeyCode.WIN_KEY,
		KeyCode.ALT,
		KeyCode.META,
		KeyCode.WIN_KEY_RIGHT,
		KeyCode.CTRL,
		KeyCode.SEMICOLON,
		KeyCode.EQUALS,
		KeyCode.CAPS_LOCK,
		KeyCode.CONTEXT_MENU,
		KeyCode.UP,
		KeyCode.LEFT,
		KeyCode.RIGHT,
		KeyCode.F1,
		KeyCode.F2,
		KeyCode.F3,
		KeyCode.F4,
		KeyCode.F5,
		KeyCode.F6,
		KeyCode.F7,
		KeyCode.F8,
		KeyCode.F9,
		KeyCode.F10,
		KeyCode.F11,
		KeyCode.F12
	].includes(currentKeyCode);
}
//#endregion
export { isValidateOpenKey };
