import { createVNode } from "vue";
//#region src/tree/utils/dropIndicator.tsx
const offset = 4;
function dropIndicatorRender(props) {
	const { dropPosition, dropLevelOffset, prefixCls, indent, direction = "ltr" } = props;
	const startPosition = direction === "ltr" ? "left" : "right";
	const endPosition = direction === "ltr" ? "right" : "left";
	const style = {
		[startPosition]: `${-dropLevelOffset * indent + 4}px`,
		[endPosition]: 0
	};
	switch (dropPosition) {
		case -1:
			style.top = `-3px`;
			break;
		case 1:
			style.bottom = `-3px`;
			break;
		default:
			style.bottom = `-3px`;
			style[startPosition] = `${indent + 4}px`;
			break;
	}
	return createVNode("div", {
		"style": style,
		"class": `${prefixCls}-drop-indicator`
	}, null);
}
//#endregion
export { dropIndicatorRender as default, offset };
