import { toTaggedKey } from "../util.js";
//#region src/RawList/useRawListScroll.ts
function useRawListScroll(ref, prefixCls, stickyGroup) {
	const holderRef = ref;
	const getStickyHeaderHeight = (targetElement) => {
		if (!stickyGroup) return 0;
		const groupHeader = targetElement.closest(`.${CSS.escape(`${prefixCls}-group-section`)}`)?.querySelector(`.${CSS.escape(`${prefixCls}-group-header`)}`);
		if (!groupHeader) return 0;
		const rect = groupHeader.getBoundingClientRect();
		const height = rect.height || rect.bottom - rect.top || groupHeader.offsetHeight;
		return Number.isFinite(height) ? height : 0;
	};
	const scrollTargetIntoView = (targetElement, align, offset, isItem) => {
		const headerOffset = isItem && align !== "bottom" ? getStickyHeaderHeight(targetElement) : 0;
		const prevTop = targetElement.style.scrollMarginTop;
		const prevBottom = targetElement.style.scrollMarginBottom;
		targetElement.style.scrollMarginTop = `${headerOffset + offset}px`;
		targetElement.style.scrollMarginBottom = `${offset}px`;
		targetElement.scrollIntoView({
			block: align === "bottom" ? "end" : align === "auto" ? "nearest" : "start",
			inline: "nearest"
		});
		targetElement.style.scrollMarginTop = prevTop;
		targetElement.style.scrollMarginBottom = prevBottom;
	};
	const scrollTo = (config) => {
		const holder = holderRef.value;
		if (!holder || config == null) return;
		if (typeof config === "number") {
			holder.scrollTop = config;
			return;
		}
		if ("key" in config || "groupKey" in config) {
			const { align = "auto", offset = 0 } = config;
			const isItem = "key" in config;
			const targetKey = isItem ? toTaggedKey(config.key, "item") : toTaggedKey(config.groupKey, "group");
			const targetElement = holder.querySelector(`[data-key="${CSS.escape(targetKey)}"]`);
			if (targetElement) scrollTargetIntoView(targetElement, align, offset, isItem);
			return;
		}
		const { left, top } = config;
		if (left !== void 0) holder.scrollLeft = left;
		if (top !== void 0) holder.scrollTop = top;
	};
	return scrollTo;
}
//#endregion
export { useRawListScroll as default };
