import { computed } from "vue";
//#region src/hooks/useGroupSegments.ts
/**
* segments representing consecutive runs of items that share the same group key.
*/
function useGroupSegments(data, group) {
	return computed(() => {
		const map = /* @__PURE__ */ new Map();
		if (!group) return map;
		data.forEach((item, index) => {
			const groupKey = typeof group.key === "function" ? group.key(item) : group.key;
			const groupItems = map.get(groupKey);
			const groupSegmentItem = {
				item,
				index
			};
			if (groupItems) groupItems.push(groupSegmentItem);
			else map.set(groupKey, [groupSegmentItem]);
		});
		return map;
	});
}
//#endregion
export { useGroupSegments as default };
